from ...ltebearer import LteBearer


class DemoBearer(LteBearer):
    """Bearer for mocked Robot tests."""

    def __init__(self, identification):
        """
        Basic initialization.
        :param identification:
        """
        super().__init__(identification)
        self.active = False

    def is_active(self):
        """
        Returns Bearer state.
        :return: boolen
        """
        return self.active

    def get_bearer_id(self):
        """
        Return wts bearer id
        :return: bearer_id
        """
        bearer_identification = self.bearer_identification['demo']['bearer_id']
        return bearer_identification


class DemoDefaultBearer(DemoBearer):
    """Default bearer for mocked Robot tests."""

    def __init__(self, identification):
        """
        Basic initialization.
        :param identification:
        """
        super().__init__(identification)
        self.active = True
